// Some portions generated by Claude
import { useMemo } from "react";
import type { LoadBatch, NamedGroup } from "./explorer-types.ts";
import type { GraphEdge, GraphNode } from "./graph-types.ts";
import { Icon } from "./icons.tsx";
import { HelpTip } from "./help-tip.tsx";

export type NavigatorPanelProps = {
  selectedIds: readonly string[];
  edges: readonly GraphEdge[];
  nodeById: ReadonlyMap<string, GraphNode>;
  namedGroups: readonly NamedGroup[];
  /** Edges of the highlighted shortest path, or null when no path is highlighted. */
  pathEdgeCount: number | null;
  onClose: () => void;
  onFindPath: () => void;
  onSelectCommonNeighbours: () => void;
  onRelayoutSelection: () => void;
  onSaveGroup: () => void;
  onClearPath: () => void;
  onSelectGroup: (group: NamedGroup) => void;
  onDeleteGroup: (group: NamedGroup) => void;
};

/** Paths and groups: shortest path, common neighbours, comparison of two nodes and named groups. */
export function NavigatorPanel({
  selectedIds,
  edges,
  nodeById,
  namedGroups,
  pathEdgeCount,
  onClose,
  onFindPath,
  onSelectCommonNeighbours,
  onRelayoutSelection,
  onSaveGroup,
  onClearPath,
  onSelectGroup,
  onDeleteGroup,
}: NavigatorPanelProps) {
  const selectedCount = selectedIds.length;
  const comparison = useMemo(() => {
    if (selectedIds.length !== 2) return null;
    const [leftId, rightId] = selectedIds;
    const predicatesFor = (nodeId: string) =>
      new Set(edges.filter((edge) => edge.source === nodeId || edge.target === nodeId).map((edge) => edge.label));
    const leftPredicates = predicatesFor(leftId);
    const rightPredicates = predicatesFor(rightId);
    return {
      left: nodeById.get(leftId),
      right: nodeById.get(rightId),
      shared: [...leftPredicates].filter((predicate) => rightPredicates.has(predicate)).sort(),
      leftOnly: [...leftPredicates].filter((predicate) => !rightPredicates.has(predicate)).sort(),
      rightOnly: [...rightPredicates].filter((predicate) => !leftPredicates.has(predicate)).sort(),
    };
  }, [edges, nodeById, selectedIds]);
  return (
    <aside
      className="filter-sidebar workbench-sidebar"
      aria-label="Graph navigation"
      onClick={(event) => event.stopPropagation()}
    >
      <div className="filter-sidebar-header">
        <div>
          <div className="panel-title">
            <h3>Paths and groups</h3>
            <HelpTip inline label="How to use paths and groups">
              <p>Select two nodes to find the shortest path between them and compare the relations they use.</p>
              <p>Select two or more nodes to select the neighbours they share.</p>
              <p>Re-layout selection arranges only the selected nodes and their neighbours.</p>
              <p>Save a selection as a group to select the same nodes again later.</p>
            </HelpTip>
          </div>
          <small>
            {selectedCount} {selectedCount === 1 ? "node" : "nodes"} selected
          </small>
        </div>
        <button
          className="workbench-action workbench-action--ghost workbench-action--icon"
          type="button"
          aria-label="Close graph navigation"
          title="Close graph navigation"
          onClick={onClose}
        >
          <Icon name="close" />
        </button>
      </div>
      <div className="navigator-actions">
        <button
          className="workbench-action workbench-action--secondary"
          type="button"
          disabled={selectedCount !== 2}
          onClick={onFindPath}
        >
          Find shortest path
        </button>
        <button
          className="workbench-action workbench-action--secondary"
          type="button"
          disabled={selectedCount < 2}
          onClick={onSelectCommonNeighbours}
        >
          Select common neighbours
        </button>
        <button
          className="workbench-action workbench-action--secondary"
          type="button"
          disabled={!selectedCount}
          onClick={onRelayoutSelection}
        >
          Re-layout selection
        </button>
        <button
          className="workbench-action workbench-action--secondary"
          type="button"
          disabled={!selectedCount}
          onClick={onSaveGroup}
        >
          Save as group
        </button>
      </div>
      {pathEdgeCount !== null && (
        <div className="path-summary">
          <strong>
            Path of {pathEdgeCount} {pathEdgeCount === 1 ? "link" : "links"}
          </strong>
          <button className="workbench-action workbench-action--ghost" type="button" onClick={onClearPath}>
            Clear highlight
          </button>
        </div>
      )}
      {comparison && (
        <section className="comparison">
          <h4>
            {comparison.left?.label} ↔ {comparison.right?.label}
          </h4>
          <div>
            <span>Both use</span>
            <p>{comparison.shared.join(" · ") || "No relations in common"}</p>
          </div>
          <div>
            <span>{comparison.left?.label}</span>
            <p>{comparison.leftOnly.join(" · ") || "—"}</p>
          </div>
          <div>
            <span>{comparison.right?.label}</span>
            <p>{comparison.rightOnly.join(" · ") || "—"}</p>
          </div>
        </section>
      )}
      <section className="named-groups">
        <h4>Saved groups</h4>
        {namedGroups.map((group) => (
          <article key={group.id}>
            <i style={{ background: group.color }} />
            <button
              type="button"
              onClick={() => onSelectGroup(group)}
            >
              <strong>{group.name}</strong>
              <span>{group.nodeIds.length} nodes</span>
            </button>
            <button
              className="workbench-action workbench-action--ghost workbench-action--icon"
              type="button"
              aria-label={`Delete group ${group.name}`}
              title={`Delete group ${group.name}`}
              onClick={() => onDeleteGroup(group)}
            >
              <Icon name="close" />
            </button>
          </article>
        ))}
        {!namedGroups.length && (
          <p>Select nodes and save them as a group to select them again later.</p>
        )}
      </section>
    </aside>
  );
}

export type LoadHistoryPanelProps = {
  batches: readonly LoadBatch[];
  onClose: () => void;
};

/** Load history: every query and expansion that added statements, newest first. */
export function LoadHistoryPanel({ batches, onClose }: LoadHistoryPanelProps) {
  return (
    <aside
      className="filter-sidebar workbench-sidebar"
      aria-label="Load history"
      onClick={(event) => event.stopPropagation()}
    >
      <div className="filter-sidebar-header">
        <div>
          <h3>Load history</h3>
          <small>{batches.length} {batches.length === 1 ? "load" : "loads"}</small>
        </div>
        <button
          className="workbench-action workbench-action--ghost workbench-action--icon"
          type="button"
          aria-label="Close load history"
          title="Close load history"
          onClick={onClose}
        >
          <Icon name="close" />
        </button>
      </div>
      <div className="provenance-list">
        {[...batches].reverse().map((batch) => (
          <details key={batch.id}>
            <summary>
              <span
                className={`completeness-dot${
                  batch.complete ? " is-complete" : ""
                }`}
              />
              <div>
                <strong>{batch.label}</strong>
                <small>
                  {batch.tripleCount} {batch.tripleCount === 1 ? "statement" : "statements"} ·{" "}
                  {batch.complete ? "complete" : "limit reached, more may exist"}
                </small>
              </div>
            </summary>
            <dl>
              <div>
                <dt>Source</dt>
                <dd>{batch.endpoint}</dd>
              </div>
              <div>
                <dt>Loaded</dt>
                <dd>{new Date(batch.loadedAt).toLocaleString()}</dd>
              </div>
              <div>
                <dt>Limit</dt>
                <dd>{batch.limit ?? "None in the query"}</dd>
              </div>
            </dl>
            <pre>{batch.query}</pre>
          </details>
        ))}
      </div>
    </aside>
  );
}
